const express = require('express');
const db = require('../db');

const app = express();

app.get('/api/services/:serviceId/span-metrics', async (req, res) => {
  const { serviceId } = req.params;

  // Validate service belongs to caller's team
  const service = await db('services')
    .where({ id: serviceId, team_id: req.user.teamId })
    .first();

  if (!service) {
    return res.status(403).json({ error: 'Access denied: Service does not belong to your team' });
  }

  const metrics = await db('service_span_metrics')
    .where({ service_id: serviceId })
    .orderBy('recorded_at', 'desc')
    .limit(24);

  if (!metrics || metrics.length === 0) {
    return res.status(404).json({ error: 'No metrics found for service' });
  }

  return res.json({ serviceId, hourlyMetrics: metrics });
});

module.exports = app;
